// 待办命令行只处理参数与输出，所有业务操作交给 task。
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"example.test/workbench-todo/task"
)

func main() { os.Exit(Run(os.Args[1:], os.Stdout, os.Stderr)) }

// Run 对应确认设计中的 cli-command，使用可传入的输出流验证退出语义。
func Run(args []string, out, stderr io.Writer) int {
	flags := flag.NewFlagSet("todo", flag.ContinueOnError)
	flags.SetOutput(stderr)
	file := flags.String("file", "tasks.json", "JSON 数据文件路径")
	if err := flags.Parse(args); err != nil {
		if err == flag.ErrHelp {
			return 0
		}
		return 2
	}
	command := flags.Args()
	fail := func(err error) int { fmt.Fprintln(stderr, err); return 2 }
	if len(command) == 0 {
		return fail(fmt.Errorf("用法：todo [-file 路径] add <标题> | done <ID> | list"))
	}
	switch command[0] {
	case "add":
		item, err := task.Add(*file, strings.Join(command[1:], " "))
		if err != nil {
			return fail(err)
		}
		fmt.Fprintf(out, "%d\t%s\n", item.ID, item.Title)
	case "done":
		if len(command) != 2 {
			return fail(fmt.Errorf("用法：done <ID>"))
		}
		id, err := strconv.ParseUint(command[1], 10, 64)
		if err != nil || id == 0 {
			return fail(fmt.Errorf("ID 必须是正整数"))
		}
		item, changed, err := task.Complete(*file, id)
		if err != nil {
			return fail(err)
		}
		label := "已经完成"
		if changed {
			label = "已完成"
		}
		fmt.Fprintf(out, "%s %d\t%s\n", label, item.ID, item.Title)
	case "list":
		if len(command) != 1 {
			return fail(fmt.Errorf("list 不接受额外参数"))
		}
		items, err := task.Pending(*file)
		if err != nil {
			return fail(err)
		}
		for _, item := range items {
			fmt.Fprintf(out, "%d\t%s\n", item.ID, item.Title)
		}
	default:
		return fail(fmt.Errorf("未知命令：%s", command[0]))
	}
	return 0
}

// Package storage 提供中立 JSON 文档读写，不了解待办字段或命令行行为。
package storage

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// ReadJSON 返回完整文档；文件不存在时保留 os.ErrNotExist 供业务层初始化状态。
func ReadJSON(path string) ([]byte, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("读取数据文件：%w", err)
	}
	if !json.Valid(data) {
		return nil, fmt.Errorf("数据文件 JSON 已损坏，原文件未修改")
	}
	return data, nil
}

// WriteJSON 用同目录临时文件原子替换，只接受有效 JSON，拒绝覆盖已损坏文档。
// 本示例不支持多个进程同时写同一文件。
func WriteJSON(path string, data []byte) error {
	if !json.Valid(data) {
		return fmt.Errorf("不能保存无效 JSON")
	}
	if _, err := ReadJSON(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	f, err := os.CreateTemp(dir, ".todo-*")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	defer f.Close()
	if _, err := f.Write(data); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Rename(f.Name(), path); err != nil {
		return err
	}
	directory, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

// Package task 维护待办规则，通过 storage 读写中立文档。
package task

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"sort"
	"strings"

	"example.test/workbench-todo/storage"
)

type Task struct {
	ID    uint64 `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

// next_id 独立保留已使用编号，完成任务不会造成 ID 重用。
type document struct {
	Version int    `json:"version"`
	NextID  uint64 `json:"next_id"`
	Tasks   []Task `json:"tasks"`
}

func read(path string) (document, error) {
	data, err := storage.ReadJSON(path)
	if errors.Is(err, os.ErrNotExist) {
		return document{Version: 1, NextID: 1, Tasks: []Task{}}, nil
	}
	if err != nil {
		return document{}, err
	}
	var doc document
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&doc); err != nil {
		return document{}, fmt.Errorf("待办文档结构无效：%w", err)
	}
	if err := decoder.Decode(new(any)); err != io.EOF {
		return document{}, fmt.Errorf("待办文档包含多余内容")
	}
	if doc.Version != 1 || doc.NextID == 0 || doc.Tasks == nil {
		return document{}, fmt.Errorf("待办文档版本、编号或任务列表无效")
	}
	seen := map[uint64]bool{}
	for _, item := range doc.Tasks {
		if item.ID == 0 || item.ID >= doc.NextID || seen[item.ID] || strings.TrimSpace(item.Title) == "" {
			return document{}, fmt.Errorf("待办文档包含重复编号或无效任务")
		}
		seen[item.ID] = true
	}
	sort.Slice(doc.Tasks, func(i, j int) bool { return doc.Tasks[i].ID < doc.Tasks[j].ID })
	return doc, nil
}

func save(path string, doc document) error {
	data, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return err
	}
	return storage.WriteJSON(path, append(data, '\n'))
}

// Add 在写入前完成所有业务校验，空标题或坏文档不会触发持久化。
func Add(path, title string) (Task, error) {
	title = strings.TrimSpace(title)
	if title == "" {
		return Task{}, fmt.Errorf("标题不能为空")
	}
	doc, err := read(path)
	if err != nil {
		return Task{}, err
	}
	if doc.NextID == math.MaxUint64 {
		return Task{}, fmt.Errorf("任务编号已用尽")
	}
	item := Task{ID: doc.NextID, Title: title}
	doc.NextID++
	doc.Tasks = append(doc.Tasks, item)
	if err := save(path, doc); err != nil {
		return Task{}, err
	}
	return item, nil
}

// Complete 的第二个返回值说明本次是否发生变化；重复完成不产生额外写入。
func Complete(path string, id uint64) (Task, bool, error) {
	doc, err := read(path)
	if err != nil {
		return Task{}, false, err
	}
	for i := range doc.Tasks {
		if doc.Tasks[i].ID != id {
			continue
		}
		if doc.Tasks[i].Done {
			return doc.Tasks[i], false, nil
		}
		doc.Tasks[i].Done = true
		if err := save(path, doc); err != nil {
			return Task{}, false, err
		}
		return doc.Tasks[i], true, nil
	}
	return Task{}, false, fmt.Errorf("任务 %d 不存在", id)
}

// Pending 每次读取磁盘，按稳定 ID 顺序返回尚未完成的任务。
func Pending(path string) ([]Task, error) {
	doc, err := read(path)
	if err != nil {
		return nil, err
	}
	result := []Task{}
	for _, item := range doc.Tasks {
		if !item.Done {
			result = append(result, item)
		}
	}
	return result, nil
}

